/**
 * @summary Update Account Settings
 */
export const zodUpdateAccountBodyFeaturesOneEmbedColorMax = 6;

export const zodUpdateAccountBodyFeaturesOneEmojiUrlMax = 256;

export const zodUpdateAccountBody = zod.object({
	prefix: zod.string().nullish().describe('Custom name prefix'),
	suffix: zod.string().nullish().describe('Custom name suffix'),
	features: zod
		.object({
			weightStyle: zod.int().nullish().describe('Name of weight style to use.'),
			weightStyleOverride: zod.coerce
				.boolean<boolean>()
				.nullish()
				.describe("Ability to override other's weight styles."),
			embedColor: zod
				.string()
				.max(zodUpdateAccountBodyFeaturesOneEmbedColorMax)
				.nullish()
				.describe('Embed color for the bot.'),
			moreInfoDefault: zod.coerce
				.boolean<boolean>()
				.nullish()
				.describe('Show \"More Info\" on weight command by default.'),
			hideShopPromotions: zod.coerce
				.boolean<boolean>()
				.nullish()
				.describe('If shop promotions should be hidden.'),
			emojiUrl: zod
				.string()
				.max(zodUpdateAccountBodyFeaturesOneEmojiUrlMax)
				.nullish()
				.describe('Custom name emoji URL.'),
		})
		.describe('Configurated features for the user')
		.nullish(),
	weightStyleId: zod.int().nullish().describe('Selected weight style for the user'),
	leaderboardStyleId: zod.int().nullish().describe('Selected leaderboard style for the user'),
	nameStyleId: zod.int().nullish().describe('Selected name style for the user'),
	pageStyleId: zod.int().nullish(),
	leaderboardFrameId: zod.int().nullish(),
	nameCardFrameId: zod.int().nullish(),
	leaderboardOverrides: zod
		.record(
			zod.string(),
			zod.object({
				style: zod.object({
					mode: zod.union([zod.literal(0), zod.literal(1), zod.literal(2)]),
					id: zod.int().nullish(),
				}),
				frame: zod.object({
					mode: zod.union([zod.literal(0), zod.literal(1), zod.literal(2)]),
					id: zod.int().nullish(),
				}),
			})
		)
		.nullish(),
	hideFromSearchIndex: zod.coerce
		.boolean<boolean>()
		.nullish()
		.describe('If the user should be hidden from browser search indexing.'),
});

